 if(!R.bDryRun && Changed) { FScopedTransaction Transaction(FText::FromString(TEXT("MCP Set Atmosphere Absorption Tent"))); C->GetOwner()->Modify(); C->SetFlags(RF_Transactional); C->Modify(); C->PreEditChange(Property); C->OtherTentDistribution=Requested; FPropertyChangedEvent Event(Property,EPropertyChangeType::ValueSet); C->PostEditChangeProperty(Event); if(!IsValid(C) || !Matches()) throw std::runtime_error("Native atmosphere setting readback mismatch; inspect undo transaction"); C->MarkPackageDirty(); }
